// FUNCTIONS //

/**
* Returns an implementation which uses a recursion cutoff equal to one, thus forcing the Strassen–Winograd algorithm for the fixture problem sizes, along with a counter of Strassen–Winograd kernel invocations.
*
* ## Notes
*
* -   Stubs are applied to the modules which directly require the stubbed modules (`./defaults.js` and `./base.js` are required by `./ndarray.js`, and `./winograd.js` is required by `./base.js`).
* -   If a stub fails to apply, the kernel is never invoked, and the invocation count remains zero.
*
* @private
* @returns {Object} object containing the implementation (`dgemmsw`) and the number of kernel invocations (`count`)
*/
function recursive() {
	var base;
	var out;

	out = {
		'dgemmsw': null,
		'count': 0
	};
	base = proxyquire( './../lib/base.js', {
		'./winograd.js': counter
	});
	out.dgemmsw = proxyquire( './../lib/ndarray.js', {
		'./defaults.js': {
			'CUTOFF': 1,
			'LEVELS': 100
		},
		'./base.js': base
	});
	return out;

	/**
	* Invokes the Strassen–Winograd kernel and increments the invocation count.
	*
	* @private
	* @returns {Float64Array} output matrix
	*/
	function counter() {
		out.count += 1;
		return winograd.apply( null, arguments );
	}
}

/**
* Performs the matrix-matrix operation described by a fixture using the default implementation and an implementation which forces recursion, and asserts that both implementations return the expected results.
*
* @private
* @param {Object} t - test object
* @param {Object} data - fixture data
*/
function check( t, data ) {
	var expected;
	var impl;
	var out;
	var a;
	var b;
	var c;

	expected = new Float64Array( data.C_out );

	// Default implementation (the fixture problem sizes are less than the default recursion cutoff, so the computation is delegated to `dgemm`)...
	a = new Float64Array( data.A );
	b = new Float64Array( data.B );
	c = new Float64Array( data.C );

	out = dgemmsw( data.transA, data.transB, data.M, data.N, data.K, data.alpha, a, data.strideA1, data.strideA2, data.offsetA, b, data.strideB1, data.strideB2, data.offsetB, data.beta, c, data.strideC1, data.strideC2, data.offsetC );
	t.strictEqual( out, c, 'returns expected value' );
	t.deepEqual( out, expected, 'returns expected value' );

	// Forced recursion (one level of the Strassen–Winograd recursion, followed by dynamic peeling of the odd inner dimension)...
	impl = recursive();

	a = new Float64Array( data.A );
	b = new Float64Array( data.B );
	c = new Float64Array( data.C );

	out = impl.dgemmsw( data.transA, data.transB, data.M, data.N, data.K, data.alpha, a, data.strideA1, data.strideA2, data.offsetA, b, data.strideB1, data.strideB2, data.offsetB, data.beta, c, data.strideC1, data.strideC2, data.offsetC );
	t.strictEqual( out, c, 'returns expected value' );
	t.deepEqual( out, expected, 'returns expected value' );
	t.deepEqual( a, new Float64Array( data.A ), 'does not mutate the first input matrix' );
	t.deepEqual( b, new Float64Array( data.B ), 'does not mutate the second input matrix' );
	t.strictEqual( impl.count > 0, true, 'invokes the Strassen–Winograd kernel' );
}


